import{p as a,bh as s,I as n,U as e}from"./chunks/framework.E7o_-qQ4.js";const c=JSON.parse('{"title":"大模型底层原理：从Transformer到GPT","description":"","frontmatter":{"title":"大模型底层原理：从Transformer到GPT","date":"2026-05-28T00:00:00.000Z","permalink":"/posts/AI/llm-principles","categories":["AI"],"tags":["AI","大模型","深度学习","Transformer"]},"headers":[],"relativePath":"posts/AI/大模型底层原理.md","filePath":"posts/AI/大模型底层原理.md"}'),l={name:"posts/AI/大模型底层原理.md"};function i(r,t,o,m,p,d){return s(),n("div",null,[...t[0]||(t[0]=[e(`<h1 id="大模型底层原理-从transformer到gpt" tabindex="-1">大模型底层原理：从Transformer到GPT <a class="header-anchor" href="#大模型底层原理-从transformer到gpt" aria-label="Permalink to &quot;大模型底层原理：从Transformer到GPT&quot;">​</a></h1><h2 id="_1-一句话定义大模型" tabindex="-1">1. 一句话定义大模型 <a class="header-anchor" href="#_1-一句话定义大模型" aria-label="Permalink to &quot;1. 一句话定义大模型&quot;">​</a></h2><p>大语言模型（LLM）的本质是：<strong>一个经过海量文本训练的神经网络，核心能力是根据已输入的上下文，预测下一个最合理的词（Token）</strong>。</p><p>它不是&quot;理解&quot;语言，而是通过统计规律学会了语言的模式和结构。当你问它问题时，它只是在不断&quot;接话&quot;——基于前文生成最可能的下文。</p><hr><h2 id="_2-核心架构-transformer" tabindex="-1">2. 核心架构：Transformer <a class="header-anchor" href="#_2-核心架构-transformer" aria-label="Permalink to &quot;2. 核心架构：Transformer&quot;">​</a></h2><p>现代大模型几乎全部采用 <strong>Transformer</strong> 架构（2017年 Google 提出）。它取代了过去依赖循环的 RNN，成为 NLP 的基石。</p><h3 id="_2-1-整体结构" tabindex="-1">2.1 整体结构 <a class="header-anchor" href="#_2-1-整体结构" aria-label="Permalink to &quot;2.1 整体结构&quot;">​</a></h3><p>Transformer 由两部分组成：</p><ul><li><strong>Encoder（编码器）</strong>：读取输入，提取语义表示。BERT 只用 Encoder。</li><li><strong>Decoder（解码器）</strong>：基于前文生成后续内容。GPT 系列只用 Decoder。</li></ul><p>大语言模型（如 GPT、Qwen、Llama）几乎都是 <strong>Decoder-only</strong> 架构。</p><h3 id="_2-2-三大核心机制" tabindex="-1">2.2 三大核心机制 <a class="header-anchor" href="#_2-2-三大核心机制" aria-label="Permalink to &quot;2.2 三大核心机制&quot;">​</a></h3><h4 id="_1-自注意力机制-self-attention" tabindex="-1">（1）自注意力机制（Self-Attention） <a class="header-anchor" href="#_1-自注意力机制-self-attention" aria-label="Permalink to &quot;（1）自注意力机制（Self-Attention）&quot;">​</a></h4><p>这是 Transformer 的灵魂。</p><p><strong>核心思想</strong>：让每个词都能&quot;看到&quot;句子中所有其他词，并动态决定该关注谁、关注多少。</p><p>例如句子：</p><blockquote><p>&quot;猫坐在垫子上，因为它累了。&quot;</p></blockquote><p>&quot;它&quot;应该关注&quot;猫&quot;而不是&quot;垫子&quot;。自注意力机制通过计算词与词之间的<strong>相关性权重</strong>，自动完成这种关联。</p><p><strong>计算过程</strong>：</p><ol><li>每个词被编码成三个向量：<strong>Query（查询）</strong>、<strong>Key（键）</strong>、<strong>Value（值）</strong></li><li>用 Query 去&quot;问&quot;所有 Key，计算相似度（点积）</li><li>相似度经过 Softmax 变成<strong>注意力权重</strong></li><li>用权重加权聚合所有 Value，得到当前词的上下文表示</li></ol><p>公式：</p><p><span class="katex-display"><span class="katex"><span class="katex-mathml"><math><semantics><mrow><mi>t</mi><mi>e</mi><mi>x</mi><mi>t</mi><mrow><mi>A</mi><mi>t</mi><mi>t</mi><mi>e</mi><mi>n</mi><mi>t</mi><mi>i</mi><mi>o</mi><mi>n</mi></mrow><mo>(</mo><mi>Q</mi><mo separator="true">,</mo><mi>K</mi><mo separator="true">,</mo><mi>V</mi><mo>)</mo><mo>=</mo><mi>t</mi><mi>e</mi><mi>x</mi><mi>t</mi><mrow><mi>s</mi><mi>o</mi><mi>f</mi><mi>t</mi><mi>m</mi><mi>a</mi><mi>x</mi></mrow><mi>l</mi><mi>e</mi><mi>f</mi><mi>t</mi><mo>(</mo><mi>f</mi><mi>r</mi><mi>a</mi><mi>c</mi><mrow><mi>Q</mi><msup><mi>K</mi><mi>T</mi></msup></mrow><mrow><mi>s</mi><mi>q</mi><mi>r</mi><mi>t</mi><mrow><msub><mi>d</mi><mi>k</mi></msub></mrow></mrow><mi>r</mi><mi>i</mi><mi>g</mi><mi>h</mi><mi>t</mi><mo>)</mo><mi>V</mi></mrow><annotation encoding="application/x-tex">text{Attention}(Q, K, V) = text{softmax}left(frac{QK^T}{sqrt{d_k}}right)V </annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.8913309999999999em;"></span><span class="strut bottom" style="height:1.1413309999999999em;vertical-align:-0.25em;"></span><span class="base displaystyle textstyle uncramped"><span class="mord mathit">t</span><span class="mord mathit">e</span><span class="mord mathit">x</span><span class="mord mathit">t</span><span class="mord displaystyle textstyle uncramped"><span class="mord mathit">A</span><span class="mord mathit">t</span><span class="mord mathit">t</span><span class="mord mathit">e</span><span class="mord mathit">n</span><span class="mord mathit">t</span><span class="mord mathit">i</span><span class="mord mathit">o</span><span class="mord mathit">n</span></span><span class="mopen">(</span><span class="mord mathit">Q</span><span class="mpunct">,</span><span class="mord mathit" style="margin-right:0.07153em;">K</span><span class="mpunct">,</span><span class="mord mathit" style="margin-right:0.22222em;">V</span><span class="mclose">)</span><span class="mrel">=</span><span class="mord mathit">t</span><span class="mord mathit">e</span><span class="mord mathit">x</span><span class="mord mathit">t</span><span class="mord displaystyle textstyle uncramped"><span class="mord mathit">s</span><span class="mord mathit">o</span><span class="mord mathit" style="margin-right:0.10764em;">f</span><span class="mord mathit">t</span><span class="mord mathit">m</span><span class="mord mathit">a</span><span class="mord mathit">x</span></span><span class="mord mathit" style="margin-right:0.01968em;">l</span><span class="mord mathit">e</span><span class="mord mathit" style="margin-right:0.10764em;">f</span><span class="mord mathit">t</span><span class="mopen">(</span><span class="mord mathit" style="margin-right:0.10764em;">f</span><span class="mord mathit" style="margin-right:0.02778em;">r</span><span class="mord mathit">a</span><span class="mord mathit">c</span><span class="mord displaystyle textstyle uncramped"><span class="mord mathit">Q</span><span class="mord"><span class="mord mathit" style="margin-right:0.07153em;">K</span><span class="vlist"><span style="top:-0.413em;margin-right:0.05em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle uncramped"><span class="mord mathit" style="margin-right:0.13889em;">T</span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span></span><span class="mord displaystyle textstyle uncramped"><span class="mord mathit">s</span><span class="mord mathit" style="margin-right:0.03588em;">q</span><span class="mord mathit" style="margin-right:0.02778em;">r</span><span class="mord mathit">t</span><span class="mord displaystyle textstyle uncramped"><span class="mord"><span class="mord mathit">d</span><span class="vlist"><span style="top:0.15em;margin-right:0.05em;margin-left:0em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle cramped"><span class="mord mathit" style="margin-right:0.03148em;">k</span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span></span></span><span class="mord mathit" style="margin-right:0.02778em;">r</span><span class="mord mathit">i</span><span class="mord mathit" style="margin-right:0.03588em;">g</span><span class="mord mathit">h</span><span class="mord mathit">t</span><span class="mclose">)</span><span class="mord mathit" style="margin-right:0.22222em;">V</span></span></span></span></span></p><p>除以 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mi>s</mi><mi>q</mi><mi>r</mi><mi>t</mi><mrow><msub><mi>d</mi><mi>k</mi></msub></mrow></mrow><annotation encoding="application/x-tex">sqrt{d_k}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.69444em;"></span><span class="strut bottom" style="height:0.8888799999999999em;vertical-align:-0.19444em;"></span><span class="base textstyle uncramped"><span class="mord mathit">s</span><span class="mord mathit" style="margin-right:0.03588em;">q</span><span class="mord mathit" style="margin-right:0.02778em;">r</span><span class="mord mathit">t</span><span class="mord textstyle uncramped"><span class="mord"><span class="mord mathit">d</span><span class="vlist"><span style="top:0.15em;margin-right:0.05em;margin-left:0em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle cramped"><span class="mord mathit" style="margin-right:0.03148em;">k</span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span></span></span></span></span> 是为了防止点积值过大导致梯度消失。</p><h4 id="_2-多头注意力-multi-head-attention" tabindex="-1">（2）多头注意力（Multi-Head Attention） <a class="header-anchor" href="#_2-多头注意力-multi-head-attention" aria-label="Permalink to &quot;（2）多头注意力（Multi-Head Attention）&quot;">​</a></h4><p>不只做一次注意力，而是<strong>并行做多次</strong>，每次关注不同的语义维度：</p><ul><li>一个头关注语法关系（主谓宾）</li><li>一个头关注语义关联（同义词）</li><li>一个头关注长距离依赖</li></ul><p>最后把所有头的结果拼接起来，形成更丰富的表示。</p><h4 id="_3-位置编码-positional-encoding" tabindex="-1">（3）位置编码（Positional Encoding） <a class="header-anchor" href="#_3-位置编码-positional-encoding" aria-label="Permalink to &quot;（3）位置编码（Positional Encoding）&quot;">​</a></h4><p>Transformer 没有循环结构，不知道词的先后顺序。因此需要<strong>显式注入位置信息</strong>：</p><ul><li><strong>绝对位置编码</strong>：给每个位置分配一个固定向量（如正弦/余弦函数）</li><li><strong>旋转位置编码（RoPE）</strong>：现代主流方案，通过旋转矩阵将位置信息融入注意力计算，支持更长的上下文</li></ul><p>Llama、Qwen 等现代模型都使用 RoPE。</p><h3 id="_2-3-前馈网络与残差连接" tabindex="-1">2.3 前馈网络与残差连接 <a class="header-anchor" href="#_2-3-前馈网络与残差连接" aria-label="Permalink to &quot;2.3 前馈网络与残差连接&quot;">​</a></h3><p>每个 Transformer Block 还包含：</p><ul><li><strong>Feed-Forward Network（FFN）</strong>：对每个位置独立做非线性变换，增加模型表达能力</li><li><strong>LayerNorm + 残差连接</strong>：稳定训练，防止梯度消失，让深层网络可训练</li></ul><p>GPT-3 有 96 层这样的 Block，堆叠越深，模型能力越强。</p><hr><h2 id="_3-训练三阶段" tabindex="-1">3. 训练三阶段 <a class="header-anchor" href="#_3-训练三阶段" aria-label="Permalink to &quot;3. 训练三阶段&quot;">​</a></h2><p>大模型的训练不是一步到位，而是分阶段完成的。</p><h3 id="_3-1-预训练-pre-training" tabindex="-1">3.1 预训练（Pre-training） <a class="header-anchor" href="#_3-1-预训练-pre-training" aria-label="Permalink to &quot;3.1 预训练（Pre-training）&quot;">​</a></h3><p><strong>目标</strong>：让模型学会语言的通用规律和世界知识。</p><ul><li><strong>数据</strong>：互联网公开文本（网页、书籍、论文、代码），通常达<strong>数万亿 Token</strong></li><li><strong>任务</strong>：自监督学习——遮住后面的词，让模型预测下一个词</li><li><strong>计算量</strong>：极大，GPT-3 用了数千张 GPU 训练数周，消耗数百万美元</li><li><strong>输出</strong>：得到一个<strong>基座模型（Base Model）</strong>，具备通用的语言理解和生成能力</li></ul><p>预训练本质上是在做<strong>无损压缩</strong>：模型学会了用更短的参数表示海量文本中的规律。</p><h3 id="_3-2-有监督微调-sft" tabindex="-1">3.2 有监督微调（SFT） <a class="header-anchor" href="#_3-2-有监督微调-sft" aria-label="Permalink to &quot;3.2 有监督微调（SFT）&quot;">​</a></h3><p>基座模型能生成文本，但不会&quot;好好回答问题&quot;。SFT 让模型学会<strong>对话格式和遵循指令</strong>。</p><ul><li><strong>数据</strong>：人工编写的&quot;问题-答案&quot;对话对，通常数十万条</li><li><strong>任务</strong>：给定问题，生成标准答案</li><li><strong>效果</strong>：模型从&quot;接话机器&quot;变成&quot;能听话、会回答的助手&quot;</li></ul><h3 id="_3-3-强化学习对齐-rlhf-dpo" tabindex="-1">3.3 强化学习对齐（RLHF / DPO） <a class="header-anchor" href="#_3-3-强化学习对齐-rlhf-dpo" aria-label="Permalink to &quot;3.3 强化学习对齐（RLHF / DPO）&quot;">​</a></h3><p>让模型的输出<strong>符合人类偏好</strong>——有用、无害、诚实。</p><p><strong>RLHF 三步骤</strong>：</p><ol><li><strong>训练奖励模型（RM）</strong>：人工对同一问题的多个回答打分，训练一个模型来评价回答好坏</li><li><strong>PPO 强化学习</strong>：用奖励模型指导基座模型优化，生成更高分的回答</li><li><strong>迭代优化</strong>：多次循环，不断提升</li></ol><p><strong>DPO（Direct Preference Optimization）</strong>：近年更流行的简化方案，直接用偏好数据优化，无需单独训练奖励模型，训练更稳定高效。</p><hr><h2 id="_4-推理过程-模型如何生成回答" tabindex="-1">4. 推理过程：模型如何生成回答 <a class="header-anchor" href="#_4-推理过程-模型如何生成回答" aria-label="Permalink to &quot;4. 推理过程：模型如何生成回答&quot;">​</a></h2><p>训练好的模型在运行时，每一步只做一件事：<strong>预测下一个 Token</strong>。</p><h3 id="_4-1-自回归生成" tabindex="-1">4.1 自回归生成 <a class="header-anchor" href="#_4-1-自回归生成" aria-label="Permalink to &quot;4.1 自回归生成&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>用户输入：&quot;请介绍Transformer&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Step 1: 输入 &quot;请介绍Transformer&quot; → 模型预测下一个词 → &quot;是&quot;</span></span>
<span class="line"><span>Step 2: 输入 &quot;请介绍Transformer是&quot; → 模型预测下一个词 → &quot;一种&quot;</span></span>
<span class="line"><span>Step 3: 输入 &quot;请介绍Transformer是一种&quot; → 模型预测下一个词 → &quot;神经网络&quot;</span></span>
<span class="line"><span>... 直到生成结束标记或达到最大长度</span></span></code></pre></div><p>这就是**自回归（Auto-regressive）**生成：每次生成的输出，又会作为下一步的输入。</p><h3 id="_4-2-从分数到文本" tabindex="-1">4.2 从分数到文本 <a class="header-anchor" href="#_4-2-从分数到文本" aria-label="Permalink to &quot;4.2 从分数到文本&quot;">​</a></h3><p>模型输出的是每个候选词的<strong>Logits（原始分数）</strong>，需要经过以下步骤才能变成实际文本：</p><ol><li><strong>Softmax 转概率</strong>：将分数变成 0~1 之间的概率分布</li><li><strong>采样策略</strong>： <ul><li><strong>Greedy（贪心）</strong>：永远选概率最高的词，结果确定但单调</li><li><strong>Temperature 采样</strong>：用温度参数调整概率分布的&quot;陡峭程度&quot; <ul><li>温度低（0.1~0.5）：保守、精准、重复性高</li><li>温度高（1.0~2.0）：创意、多样、可能胡言乱语</li></ul></li><li><strong>Top-K / Top-P（Nucleus）采样</strong>：只在概率最高的前 K 个或累积概率达 P 的词中采样，平衡多样性和质量</li></ul></li></ol><h3 id="_4-3-关键超参数" tabindex="-1">4.3 关键超参数 <a class="header-anchor" href="#_4-3-关键超参数" aria-label="Permalink to &quot;4.3 关键超参数&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">参数</th><th style="text-align:left;">作用</th><th style="text-align:left;">推荐取值</th></tr></thead><tbody><tr><td style="text-align:left;">Temperature</td><td style="text-align:left;">控制生成随机性</td><td style="text-align:left;">0.3（精准）~ 1.0（平衡）</td></tr><tr><td style="text-align:left;">Top-P</td><td style="text-align:left;">核采样阈值</td><td style="text-align:left;">0.9（常用）</td></tr><tr><td style="text-align:left;">Max Tokens</td><td style="text-align:left;">最大生成长度</td><td style="text-align:left;">根据任务设定</td></tr><tr><td style="text-align:left;">Repetition Penalty</td><td style="text-align:left;">重复惩罚</td><td style="text-align:left;">1.0~1.2</td></tr></tbody></table><hr><h2 id="_5-模型规模与能力的关系" tabindex="-1">5. 模型规模与能力的关系 <a class="header-anchor" href="#_5-模型规模与能力的关系" aria-label="Permalink to &quot;5. 模型规模与能力的关系&quot;">​</a></h2><h3 id="_5-1-参数规模" tabindex="-1">5.1 参数规模 <a class="header-anchor" href="#_5-1-参数规模" aria-label="Permalink to &quot;5.1 参数规模&quot;">​</a></h3><p>大模型的&quot;大&quot;主要体现在参数量：</p><table tabindex="0"><thead><tr><th style="text-align:left;">模型</th><th style="text-align:left;">参数量</th><th style="text-align:left;">特点</th></tr></thead><tbody><tr><td style="text-align:left;">GPT-3</td><td style="text-align:left;">175B</td><td style="text-align:left;">开启了超大规模模型时代</td></tr><tr><td style="text-align:left;">LLaMA 2</td><td style="text-align:left;">7B / 13B / 70B</td><td style="text-align:left;">开源标杆，70B 逼近 GPT-3.5</td></tr><tr><td style="text-align:left;">GPT-4</td><td style="text-align:left;">~1.8T（MoE）</td><td style="text-align:left;">混合专家架构，推理时激活约 10%</td></tr><tr><td style="text-align:left;">Qwen2.5</td><td style="text-align:left;">0.5B ~ 72B</td><td style="text-align:left;">国产开源，小尺寸也能用</td></tr></tbody></table><h3 id="_5-2-缩放定律-scaling-laws" tabindex="-1">5.2 缩放定律（Scaling Laws） <a class="header-anchor" href="#_5-2-缩放定律-scaling-laws" aria-label="Permalink to &quot;5.2 缩放定律（Scaling Laws）&quot;">​</a></h3><p>OpenAI 2020年的研究发现：</p><blockquote><p><strong>模型性能随计算量、参数量、数据量三者同时提升而可预测地增长。</strong></p></blockquote><p>公式化表达：</p><p><span class="katex-display"><span class="katex"><span class="katex-mathml"><math><semantics><mrow><mi>L</mi><mo>(</mo><mi>N</mi><mo>)</mo><mo>∝</mo><msup><mi>N</mi><mrow><mo>−</mo><mi>α</mi></mrow></msup></mrow><annotation encoding="application/x-tex">L(N) \\propto N^{-\\alpha} </annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.821331em;"></span><span class="strut bottom" style="height:1.071331em;vertical-align:-0.25em;"></span><span class="base displaystyle textstyle uncramped"><span class="mord mathit">L</span><span class="mopen">(</span><span class="mord mathit" style="margin-right:0.10903em;">N</span><span class="mclose">)</span><span class="mrel">∝</span><span class="mord"><span class="mord mathit" style="margin-right:0.10903em;">N</span><span class="vlist"><span style="top:-0.41300000000000003em;margin-right:0.05em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle uncramped"><span class="mord scriptstyle uncramped"><span class="mord">−</span><span class="mord mathit" style="margin-right:0.0037em;">α</span></span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span></span></span></span></span></p><p>其中 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mi>L</mi></mrow><annotation encoding="application/x-tex">L</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.68333em;"></span><span class="strut bottom" style="height:0.68333em;vertical-align:0em;"></span><span class="base textstyle uncramped"><span class="mord mathit">L</span></span></span></span> 是损失（越小越好），<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mi>N</mi></mrow><annotation encoding="application/x-tex">N</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.68333em;"></span><span class="strut bottom" style="height:0.68333em;vertical-align:0em;"></span><span class="base textstyle uncramped"><span class="mord mathit" style="margin-right:0.10903em;">N</span></span></span></span> 是参数量。这意味着：<strong>只要扩大规模，模型就会变强</strong>——这是大模型浪潮的理论基础。</p><h3 id="_5-3-涌现能力-emergent-abilities" tabindex="-1">5.3 涌现能力（Emergent Abilities） <a class="header-anchor" href="#_5-3-涌现能力-emergent-abilities" aria-label="Permalink to &quot;5.3 涌现能力（Emergent Abilities）&quot;">​</a></h3><p>当模型大到一定程度（通常数十亿参数以上），会突然展现出小模型没有的能力：</p><ul><li>上下文学习（In-Context Learning）：给几个示例就能学会新任务</li><li>思维链（Chain-of-Thought）：分步推理复杂问题</li><li>指令遵循：理解并执行复杂指令</li></ul><p>这些能力不是显式训练的，而是<strong>规模达到阈值后自然出现</strong>的。</p><hr><h2 id="_6-现代大模型的关键技术" tabindex="-1">6. 现代大模型的关键技术 <a class="header-anchor" href="#_6-现代大模型的关键技术" aria-label="Permalink to &quot;6. 现代大模型的关键技术&quot;">​</a></h2><h3 id="_6-1-上下文窗口-context-window" tabindex="-1">6.1 上下文窗口（Context Window） <a class="header-anchor" href="#_6-1-上下文窗口-context-window" aria-label="Permalink to &quot;6.1 上下文窗口（Context Window）&quot;">​</a></h3><p>模型一次能处理的 Token 数量。早期 GPT-3 只有 2K，现在主流模型支持 128K 甚至 1M+：</p><ul><li><strong>RoPE 基频调整</strong>：通过修改位置编码的基频，外推更长上下文</li><li><strong>LongRoPE / YaRN</strong>：更高级的外推技术，让模型&quot;记住&quot;更远的内容</li><li><strong>Ring Attention / 稀疏注意力</strong>：降低长序列的计算复杂度</li></ul><h3 id="_6-2-量化-quantization" tabindex="-1">6.2 量化（Quantization） <a class="header-anchor" href="#_6-2-量化-quantization" aria-label="Permalink to &quot;6.2 量化（Quantization）&quot;">​</a></h3><p>大模型占用显存巨大，量化通过降低参数精度来减少体积：</p><table tabindex="0"><thead><tr><th style="text-align:left;">精度</th><th style="text-align:left;">每参数占用</th><th style="text-align:left;">70B 模型显存</th></tr></thead><tbody><tr><td style="text-align:left;">FP32</td><td style="text-align:left;">4 字节</td><td style="text-align:left;">~280 GB</td></tr><tr><td style="text-align:left;">FP16 / BF16</td><td style="text-align:left;">2 字节</td><td style="text-align:left;">~140 GB</td></tr><tr><td style="text-align:left;">INT8</td><td style="text-align:left;">1 字节</td><td style="text-align:left;">~70 GB</td></tr><tr><td style="text-align:left;">INT4 / NF4</td><td style="text-align:left;">0.5 字节</td><td style="text-align:left;">~35 GB</td></tr></tbody></table><p>量化后性能损失通常很小（&lt;2%），但显存减半甚至减到 1/4，让消费级显卡也能跑大模型。</p><h3 id="_6-3-kv-cache" tabindex="-1">6.3 KV Cache <a class="header-anchor" href="#_6-3-kv-cache" aria-label="Permalink to &quot;6.3 KV Cache&quot;">​</a></h3><p>自回归生成时，每次都要重新计算所有前文。KV Cache 把已经算好的 Key 和 Value 存起来，下次直接复用：</p><ul><li>生成第 N 个词时，只需计算 1 个新位置的注意力</li><li>时间复杂度从 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mi>O</mi><mo>(</mo><msup><mi>N</mi><mn>2</mn></msup><mo>)</mo></mrow><annotation encoding="application/x-tex">O(N^2)</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.8141079999999999em;"></span><span class="strut bottom" style="height:1.064108em;vertical-align:-0.25em;"></span><span class="base textstyle uncramped"><span class="mord mathit" style="margin-right:0.02778em;">O</span><span class="mopen">(</span><span class="mord"><span class="mord mathit" style="margin-right:0.10903em;">N</span><span class="vlist"><span style="top:-0.363em;margin-right:0.05em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle uncramped"><span class="mord mathrm">2</span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span><span class="mclose">)</span></span></span></span> 降到 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mi>O</mi><mo>(</mo><mi>N</mi><mo>)</mo></mrow><annotation encoding="application/x-tex">O(N)</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.75em;"></span><span class="strut bottom" style="height:1em;vertical-align:-0.25em;"></span><span class="base textstyle uncramped"><span class="mord mathit" style="margin-right:0.02778em;">O</span><span class="mopen">(</span><span class="mord mathit" style="margin-right:0.10903em;">N</span><span class="mclose">)</span></span></span></span></li><li>代价是额外显存占用（与序列长度成正比）</li></ul><p>这是大模型推理加速的核心技术之一。</p><hr><h2 id="_7-总结" tabindex="-1">7. 总结 <a class="header-anchor" href="#_7-总结" aria-label="Permalink to &quot;7. 总结&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">维度</th><th style="text-align:left;">核心要点</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>本质</strong></td><td style="text-align:left;">基于前文预测下一个 Token 的概率模型</td></tr><tr><td style="text-align:left;"><strong>架构</strong></td><td style="text-align:left;">Transformer Decoder，核心是 Self-Attention</td></tr><tr><td style="text-align:left;"><strong>训练</strong></td><td style="text-align:left;">预训练 → SFT → RLHF/DPO，三阶段递进</td></tr><tr><td style="text-align:left;"><strong>推理</strong></td><td style="text-align:left;">自回归生成，Temperature/Top-P 控制风格</td></tr><tr><td style="text-align:left;"><strong>规模</strong></td><td style="text-align:left;">参数越多、数据越多、计算越多，能力越强</td></tr><tr><td style="text-align:left;"><strong>部署</strong></td><td style="text-align:left;">量化 + KV Cache，降低资源消耗</td></tr></tbody></table><p>理解这些底层原理，能帮助你：</p><ol><li><strong>更好地使用模型</strong>：知道为什么 Temperature 0.3 适合代码、1.0 适合创意写作</li><li><strong>排查问题</strong>：明白&quot;幻觉&quot;源于概率采样的随机性和训练数据的局限</li><li><strong>评估模型</strong>：不被营销参数迷惑，关注架构、训练数据和对齐质量</li></ol><hr><blockquote><p>大模型不是魔法，它是统计学、线性代数、优化理论和工程实践的结晶。理解原理，才能真正驾驭它。</p></blockquote>`,96)])])}const g=a(l,[["render",i]]);export{c as __pageData,g as default};
